    'privacy.title': 'Kebijakan Privasi',
    'privacy.breadcrumb': 'Kebijakan Privasi',
    'privacy.lastUpdated': 'Terakhir diperbarui:',
    'privacy.intro': 'Kebijakan Privasi ini menjelaskan bagaimana Baytino mengumpulkan, menggunakan, dan melindungi informasi pribadi Anda.',
    'privacy.s1': '1. Informasi yang Kami Kumpulkan',
    'privacy.s2': '2. Cara Kami Menggunakan Informasi',
    'privacy.s3': '3. Berbagi Informasi',
    'privacy.s4': '4. Cookie & Pelacakan',
    'privacy.s5': '5. Penyimpanan Data',
    'privacy.s6': '6. Keamanan',
    'privacy.s7': '7. Hak Anda',
    'privacy.s8': '8. Tautan Pihak Ketiga',
