    'privacy.title': 'Politique de confidentialité',
    'privacy.breadcrumb': 'Politique de confidentialité',
    'privacy.lastUpdated': 'Dernière mise à jour:',
    'privacy.intro': 'Cette politique explique comment Baytino collecte, utilise et protège vos informations personnelles.',
    'privacy.s1': '1. Informations que nous collectons',
    'privacy.s2': '2. Utilisation de vos informations',
    'privacy.s3': '3. Partage de vos informations',
    'privacy.s4': '4. Cookies et suivi',
    'privacy.s5': '5. Conservation des données',
