    'privacy.lastUpdated': 'Kemas kini terakhir:',
    'privacy.intro': 'Dasar Privasi ini menerangkan bagaimana Baytino mengumpul, menggunakan dan melindungi maklumat peribadi anda.',
    'privacy.s1': '1. Maklumat yang Kami Kumpulkan',
    'privacy.s2': '2. Cara Kami Menggunakan Maklumat',
    'privacy.s3': '3. Berkongsi Maklumat',
    'privacy.s4': '4. Kuki & Penjejakan',
    'privacy.s5': '5. Penyimpanan Data',
    'privacy.s6': '6. Keselamatan',
    'privacy.s7': '7. Hak Anda',
    'privacy.s8': '8. Pautan Pihak Ketiga',
